CREATE FUNCTION public.pm_validate_b1_revenue_fixture() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE caller uuid:=auth.uid(); p uuid:=gen_random_uuid(); st uuid:=gen_random_uuid(); en uuid:=gen_random_uuid(); pm uuid:='8e8fa5d7-e287-4d0a-94f6-587fce848200'; pm_resource uuid:='89b45a37-9c89-4e75-a55c-e2bf9a6fd1fb'; author uuid:='0c3f231e-ac31-4cc3-89e7-e98d920eacc6'; result jsonb; row_entry public.pm_time_entries; BEGIN IF NOT public.has_role(caller,'admin') THEN RAISE EXCEPTION 'Forbidden' USING ERRCODE='42501'; END IF; IF public.pm_project_b1_active() THEN RAISE EXCEPTION 'B1 must remain OFF'; END IF; BEGIN INSERT INTO public.pm_projects(id,name,start_date,status,sold_fee) VALUES(p,'[QA DISPOSABLE] B1 revenue 2026-11-04','2026-11-04','active',1000); INSERT INTO public.pm_stages(id,project_id,name,start_date,end_date,budget,status) VALUES(st,p,'[QA DISPOSABLE] B1 earned revenue','2026-11-04','2026-11-06',1000,'active'); PERFORM public.pm_change_project_team(p,pm_resource,'manager',false,'QA B1 revenue disposable only'); PERFORM public.pm_change_project_access(p,pm_resource,'{"financials":true,"budget_cost":true,"expenses":true,"supplier_fees":true}',1,'QA B1 revenue disposable only'); INSERT INTO public.pm_time_entries(id,user_id,entry_date,hours,billable,pm_stage_id,entry_type,notes) VALUES(en,author,'2026-11-04',8,true,st,'project','[QA DISPOSABLE] B1 revenue'); SELECT * INTO row_entry FROM public.pm_time_entries WHERE id=en; PERFORM set_config('request.jwt.claim.sub',pm::text,true); PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',pm,'role','authenticated')::text,true); result:=jsonb_build_object('project',p,'stage',st,'entryId',en,'contract',public.pm_b1_redact_proposed(jsonb_build_object('sold_fee',1000),p,'project'),'entry',public.pm_b1_redact_proposed(to_jsonb(row_entry),p,'entry'),'resources',(SELECT jsonb_agg(x) FROM public.pm_b1_financial_resources(p,true) x),'areas',public.pm_project_viewer_areas(p)); RAISE EXCEPTION 'B1_REVENUE_ROLLBACK' USING ERRCODE='ZB002'; EXCEPTION WHEN SQLSTATE 'ZB002' THEN NULL; END; IF EXISTS(SELECT 1 FROM public.pm_projects WHERE id=p) OR EXISTS(SELECT 1 FROM public.pm_stages WHERE id=st) OR EXISTS(SELECT 1 FROM public.pm_time_entries WHERE id=en) OR public.pm_project_b1_active() THEN RAISE EXCEPTION 'Fixture or gate preservation failed'; END IF; RETURN result||jsonb_build_object('rolledBack',true,'gateOff',true); END $$;
REVOKE ALL ON FUNCTION public.pm_validate_b1_revenue_fixture() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.pm_validate_b1_revenue_fixture() TO authenticated,service_role;
COMMENT ON FUNCTION public.pm_validate_b1_revenue_fixture() IS 'Admin-only single throwaway project, all-four-ON PM and eight-hour entry. Writes only generated fixture IDs inside an always-rolled-back subtransaction; preserves real rows, locked-cost trigger and B1 OFF.';